(() => {
const stops = [
 {id:'start',start:'10:00',end:'10:10',type:'出發',title:'松山車站集合，步行前往早餐',text:'從臺鐵松山車站出站，依 CITYLINK 松山壹號店指標前往 3 樓。預留找路與上下樓時間。',place:'臺北市信義區松山路11號',icon:'↗'},
 {id:'breakfast',start:'10:10',end:'11:00',type:'早餐',title:'路易莎・松山蔦屋門市',text:'用一份輕食與咖啡慢慢開啟一天；實際餐點依門市供應。早餐留點胃口，午餐再吃小籠包。',place:'CITYLINK 松山壹號店 3F｜松山路11號',hours:'官方公告：平日 07:30–21:00；週末及例假日 09:00–21:00。',source:'https://www.citylink.tw/songshan/?p=7755',sourceLabel:'商場官方門市資訊',map:'路易莎 松山蔦屋門市 台北市信義區松山路11號',tel:'0227486613',icon:'☕',meal:true},
 {id:'songshan',start:'11:00',end:'11:30',type:'散步',title:'松山站周邊散步、準備搭車',text:'在車站周邊放慢腳步，預留洗手間與進站時間。此段可吸收早餐候位延誤，不另安排一餐。',icon:'✳'},
 {id:'metro',start:'11:30',end:'12:20',type:'捷運',title:'松山 → 中山轉乘 → 台北101／世貿',text:'松山 G19 搭綠線往新店方向，在中山 G14／R11 轉紅線往廣慈／奉天宮方向，至台北101／世貿 R03 下車，再步行至 101 B1。安排 50 分鐘含候車、轉乘與步行，非即時到站預測。',source:'https://www.metro.taipei/cp.aspx?n=73B51F32ED23C5E1',sourceLabel:'北捷官方路線與車站資訊',icon:'⇄'},
 {id:'queue',start:'12:20',end:'13:00',type:'候位',title:'鼎泰豐現場取號，留 40 分鐘緩衝',text:'抵達後先確認現場等候時間。13:00 入座為規劃目標，並非已訂位；若候位較久，優先縮短午後散步，保留 17:00 晚餐。',source:'https://www.dintaifung.com.tw/store.php',sourceLabel:'鼎泰豐門市與候位資訊',icon:'◷'},
 {id:'lunch',start:'13:00',end:'14:00',type:'午餐',title:'鼎泰豐・101 店',text:'建議以小籠包搭配炒飯或麵食，份量依人數與胃口調整。這餐安排 60 分鐘，實際進餐時間依現場候位順延。',place:'臺北市信義區市府路45號 B1',hours:'出發前請查看官方 101 店當日營業與候位資訊。',source:'https://www.dintaifung.com.tw/store.php',sourceLabel:'鼎泰豐官方門市資訊',map:'鼎泰豐101店 台北市信義區市府路45號',tel:'0281017799',icon:'🥟',meal:true},
 {id:'walk',start:'14:00',end:'15:00',type:'散步',title:'四四南村戶外散步',text:'從 101 步行至四四南村周邊，看看老屋、拍攝城市街景。這一小時含步行；以戶外空間為主，不依賴展館開放。下雨則改逛 101 商場。',map:'四四南村 台北',icon:'⌂'},
 {id:'free',start:'15:00',end:'16:30',type:'自由時間',title:'信義商圈逛街與休息',text:'慢慢走回信義商圈，依體力選擇逛街或坐下休息。這 90 分鐘也是午餐候位超時的彈性空間；不額外安排下午茶套餐。',icon:'✳'},
 {id:'dinner-walk',start:'16:30',end:'17:00',type:'步行',title:'前往新光三越 A9，準備晚餐',text:'預留步行、找路與搭電梯時間，於 17:00 抵達 A9 館 8 樓。建議事先預約晚餐，並告知希望 18:00 前結束。',map:'欣葉台菜 信義A9店 台北',icon:'↗'},
 {id:'dinner',start:'17:00',end:'18:00',type:'晚餐',title:'欣葉台菜・信義 A9 店',text:'用台菜結束一日散策。依同行人數搭配菜色；一人用餐可先詢問適合份量。預留一小時用餐，點餐時告知結束時間。',place:'臺北市信義區松壽路9號 8F',hours:'官方晚餐時段：17:00–21:30；最後點餐 21:00。',source:'https://www.shinyeh.com.tw/content/zh/brand/Store.aspx?BrandId=1&Id=5',sourceLabel:'欣葉官方資訊與訂位入口',map:'欣葉台菜 信義A9店 台北市信義區松壽路9號',tel:'0287861234',icon:'🍲',meal:true}
];
const storageKey='metro-songshan-day-v1';let completed=[];try{const stored=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(stored))completed=stored.filter(id=>stops.some(s=>s.id===id));}catch{}
const minutes=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);
const total=stops.reduce((n,s)=>n+minutes(s.end)-minutes(s.start),0);
const mapLink=q=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);
const root=document.querySelector('#day-plan');
root.innerHTML=`<div class="section-head"><div><div class="eyebrow">YOUR DAY, WELL SPENT</div><h2 id="plan-title">松山出發，三餐慢旅行。</h2></div><span class="plan-label">專屬行程 · 真實店家</span></div><div class="plan-stats"><div><small>出發 → 結束</small><strong>10:00 — 18:00</strong></div><div><small>行程長度</small><strong>${total/60} 小時 <em>含交通及候位</em></strong></div><div><small>用餐安排</small><strong>早餐・午餐・晚餐</strong></div><div><small>預算設定</small><strong>金額不限</strong></div></div><div class="plan-route" aria-label="行程路線"><span><i class="dot" style="--line:#52856a"></i> 松山</span><b>→</b><span>中山 <small>綠線轉紅線</small></span><b>→</b><span><i class="dot" style="--line:#cf5048"></i> 台北101／世貿</span><b>→</b><span>信義 A9</span></div><div class="plan-layout"><div class="timeline">${stops.map(s=>`<article class="plan-stop ${s.meal?'meal-stop':''}" data-stop="${s.id}"><div class="plan-time"><strong>${s.start}</strong><small>${s.end}</small><span>${minutes(s.end)-minutes(s.start)} 分鐘</span></div><div class="stop-content"><div class="stop-top"><span class="plan-type">${s.icon} ${s.type}</span><label class="complete-label"><input type="checkbox" data-complete="${s.id}" ${completed.includes(s.id)?'checked':''} aria-label="標記完成：${s.title}"> 完成</label></div><h3>${s.title}</h3><p>${s.text}</p>${s.place?`<div class="plan-place">⌖ ${s.place}</div>`:''}${s.hours?`<div class="plan-hours">${s.hours}</div>`:''}<div class="plan-links">${s.map?`<a href="${mapLink(s.map)}" target="_blank" rel="noopener noreferrer">地圖找店 ↗</a>`:''}${s.source?`<a href="${s.source}" target="_blank" rel="noopener noreferrer">${s.sourceLabel} ↗</a>`:''}${s.tel?`<a href="tel:${s.tel}">致電店家</a>`:''}</div></div></article>`).join('')}<div class="plan-end"><span>18:00</span><strong>在信義區，完成今天的好食光。</strong><p>本行程不含返回松山的交通時間。</p></div></div><aside class="plan-aside"><div class="plan-summary"><div class="eyebrow">MY DAY CHECKLIST</div><h3>今天，慢慢吃。</h3><p id="plan-progress" role="status"></p><progress id="plan-meter" max="${stops.length}" value="0" aria-label="行程完成進度"></progress><button id="download-plan" class="plan-primary">下載文字行程 ↓</button><button id="clear-plan" class="plan-secondary">重設完成進度</button><small>完成狀態會儲存在此裝置。</small></div><div class="plan-tips"><h3>出發前的小提醒</h3><p>• 尚未指定出遊日期，營業日與特殊休假需於出發前確認。</p><p>• 欣葉建議預約 17:00；目前未代訂位。</p><p>• 鼎泰豐預留 40 分鐘候位，超時可壓縮午後自由時間；若等候會影響晚餐，改在 101 商場選擇可即時入座的餐廳。</p><p>• 金額不限代表不設花費上限，餐費、車資及購物依實際消費支付。</p><p>• 時間為規劃估計，並非即時交通或保證入座時間。</p></div></aside></div><p class="plan-footnote">店家資訊查核：2026/11/13 · 來源連結附於各站。此區為真實店家行程；下方探索區仍為示範資料。</p>`;
function sync(){document.querySelector('#plan-progress').textContent=`已完成 ${completed.length} / ${stops.length} 個行程步驟`;document.querySelector('#plan-meter').value=completed.length;root.querySelectorAll('[data-stop]').forEach(el=>el.classList.toggle('is-complete',completed.includes(el.dataset.stop)));}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(completed));}catch{toast('無法儲存到此裝置，本次進度仍保留');}}
root.addEventListener('change',e=>{const id=e.target.dataset.complete;if(!id)return;completed=completed.filter(x=>x!==id);if(e.target.checked)completed.push(id);persist();sync();});
document.querySelector('#clear-plan').onclick=()=>{completed=[];root.querySelectorAll('[data-complete]').forEach(el=>el.checked=false);persist();sync();toast('已重設本日行程進度');};
document.querySelector('#download-plan').onclick=()=>{const text=['一站一味｜松山出發・8 小時一日三餐','10:00–18:00｜預算不限｜信義區結束，不含回程','出遊日期未指定；營業與候位請出發前確認。','',...stops.map(s=>`${s.start}–${s.end} ${s.type}｜${s.title}\n${s.text}${s.place?'\n'+s.place:''}${s.hours?'\n'+s.hours:''}${s.source?'\n官方資訊：'+s.source:''}${s.map?'\n地圖：'+mapLink(s.map):''}`),'','查核日期：2026/11/13。未代訂位；交通與候位均為規劃估計。'].join('\n\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='松山出發-8小時三餐行程.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已產生文字行程');};sync();
})();
